package com.tradechameleon.trading;

import com.tradechameleon.shared.Side;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

/**
 * An order as stored and as returned by the API.
 *
 * @param stopPrice  trigger price of STOP and STOP_LIMIT orders
 * @param stopLoss   stop-loss to attach to the position once a BUY fills
 * @param takeProfit take-profit to attach to the position once a BUY fills
 * @param triggered  a STOP_LIMIT whose stop was hit and now rests as a limit order
 * @param origin     CLIENT, or STOP_LOSS / TAKE_PROFIT for orders generated by position protection
 */
public record Order(
        UUID id,
        String tenantId,
        String userId,
        String symbol,
        Side side,
        OrderType type,
        BigDecimal quantity,
        BigDecimal limitPrice,
        BigDecimal stopPrice,
        BigDecimal stopLoss,
        BigDecimal takeProfit,
        OrderStatus status,
        boolean triggered,
        Origin origin,
        BigDecimal fillPrice,
        String rejectReason,
        Instant createdAt,
        Instant updatedAt) {

    public enum OrderType { MARKET, LIMIT, STOP, STOP_LIMIT }

    public enum OrderStatus { OPEN, FILLED, CANCELLED, REJECTED }

    public enum Origin { CLIENT, STOP_LOSS, TAKE_PROFIT }

    Order filled(BigDecimal price, Instant at) {
        return new Order(id, tenantId, userId, symbol, side, type, quantity, limitPrice, stopPrice, stopLoss,
                takeProfit, OrderStatus.FILLED, triggered, origin, price, null, createdAt, at);
    }
}
